\section{Introduction}

\subsection{The counting problem}
Let $K$ be an algebraic number field with ring of integers $\mathcal{O}_K$ and ideal class group
$\Cl(K)$, a finite abelian group of order $h_K$, the class number. Class field theory attaches to
$K$ its Hilbert class field $H$, the maximal unramified abelian extension of $K$, and the Artin map
gives a canonical isomorphism $\Gal(H/K) \cong \Cl(K)$.

We work with the abstract shape of this situation, which we call a \emph{class field datum}: a
finite Galois extension $H/K$ together with a group isomorphism
$e : \Gal(H/K) \to \Cl(K)$. Everything below is a consequence of that datum.

The fundamental theorem of Galois theory gives an inclusion-reversing bijection between the
intermediate fields $K \subseteq F \subseteq H$ and the subgroups of $\Gal(H/K)$, with
$[F:K] = [\Gal(H/K) : \Gal(H/F)]$. Composing with $e$ we obtain the counting principle: a class
field datum for $K$ has exactly $\#\Sub(\Cl(K))$ intermediate fields, and the field attached to
$A \le \Cl(K)$ has degree $[\Cl(K):A]$ over $K$.

\subsection{Why the class number is insufficient}
Two abelian groups of the same order can have very different subgroup lattices. At order $4$ the
cyclic group has $3$ subgroups and the Klein four group has $5$; at order $p^{2}$ the gap is $3$
versus $p+3$; at order $12$ it is $6$ versus $10$. All of these are proved below as instances of
general theorems.

\subsection{What must be proved about $q$-binomials}
For an elementary abelian class group $(\Z/p)^{r}$ the subgroups are $\F_p$-subspaces, and their
number in each dimension is a Gaussian binomial coefficient. The classical derivation is geometric
and therefore restricted to bases $q$ that are cardinalities of actual finite fields; moreover it
does not by itself prove that the defining quotient is an exact division of integers. Section
\ref{sec:qbin} builds the theory arithmetically, uniformly in $q \ge 2$. Section \ref{sec:groups}
does the group theory, Section \ref{sec:fields} the class field consequences, and Sections
\ref{sec:algos}--\ref{sec:future} algorithms, applications and open directions.

\subsection{Conventions}
$q,n,k,r,s$ are non-negative integers and $p$ is prime; $d(N)$ is the number of positive divisors
of $N$; $\#\Sub(G)$ is the number of subgroups of a finite group $G$; empty products are $1$; all
groups are finite.

\section{Gaussian binomial coefficients over an arbitrary base}\label{sec:qbin}

\subsection{Definitions}

\begin{definition}[Gaussian binomial coefficient]
For integers $q,n,k \ge 0$ set
\[
  \binom{n}{k}_{\!q} \;=\; \left\lfloor
  \frac{\prod_{i=0}^{k-1}\bigl(q^{n}-q^{i}\bigr)}{\prod_{i=0}^{k-1}\bigl(q^{k}-q^{i}\bigr)}
  \right\rfloor,
\]
the truncated quotient of two non-negative integers. A principal result below is that for
$q \ge 2$ no truncation occurs.
\end{definition}

\begin{definition}[Recursive $q$-binomial]
Define $B_q(n,k)$ by $B_q(0,0)=1$, $B_q(0,k+1)=0$, $B_q(n+1,0)=1$ and
\[
  B_q(n+1,k+1) \;=\; B_q(n,k) + q^{\,k+1}B_q(n,k+1).
\]
\end{definition}

\begin{definition}[$q$-factorial]
$[m]_q! \;=\; \prod_{j=0}^{m-1}\bigl(q^{\,j+1}-1\bigr) = (q-1)(q^{2}-1)\cdots(q^{m}-1) \in \Z$,
with $[0]_q!=1$. Computing in $\Z$ rather than in $\mathbb{N}$ is essential: all the algebra below
involves differences.
\end{definition}

\begin{definition}[Galois number and $q$-weighted row sum]
$G_q(n) = \sum_{k=0}^{n}\binom{n}{k}_q$ and $S_q(n) = \sum_{k=0}^{n} q^{k}\binom{n}{k}_q$.
\end{definition}

\subsection{Elementary properties}

\begin{lemma}\label{lem:elem}
$B_q(n,0)=1$; $B_q(0,k)=0$ for $k \ge 1$; $B_q(n,k)=0$ whenever $n<k$; and $B_q(n,n)=1$.
\end{lemma}

\begin{proof}
The first two are defining clauses. Vanishing above the diagonal is an induction on $n$: if
$n+1<k+1$ then both $B_q(n,k)$ and $B_q(n,k+1)$ vanish inductively. Then
$B_q(n+1,n+1)=B_q(n,n)+q^{n+1}B_q(n,n+1)=B_q(n,n)$, and induction gives $1$.
\end{proof}

\begin{lemma}\label{lem:factpos}
If $q \ge 2$ then $[m]_q!>0$ for all $m$, since each factor $q^{j+1}-1 \ge q-1 > 0$.
\end{lemma}

\subsection{The $q$-factorial identity}

\begin{theorem}[$q$-factorial identity]\label{thm:factid}
For all $q$ and all $k \le n$,
\[
  [k]_q!\;[n-k]_q!\;B_q(n,k) \;=\; [n]_q! \qquad \text{in } \Z .
\]
\end{theorem}

\begin{proof}
Induction on $n$. For $n=0$ only $k=0$ occurs and both sides are $1$. For the step let
$k+1 \le n+1$ and put $m=n-k$.

If $k=n$ then $B_q(n+1,n+1)=1$ by Lemma \ref{lem:elem} and both sides equal $[n+1]_q!$.

If $k<n$, apply the recursion:
\[
 [k+1]_q!\,[m]_q!\,B_q(n+1,k+1)
 = [k+1]_q!\,[m]_q!\,B_q(n,k) + q^{k+1}[k+1]_q!\,[m]_q!\,B_q(n,k+1).
\]
Write $[k+1]_q! = [k]_q!\,(q^{k+1}-1)$ in the first summand and $[m]_q! = [m-1]_q!\,(q^{m}-1)$ in
the second (legitimate as $m \ge 1$). The inductive hypothesis at $(n,k)$ and at $(n,k+1)$, noting
$n-(k+1)=m-1$, turns the right-hand side into
\[
  \bigl(q^{k+1}-1\bigr)[n]_q! + q^{k+1}\bigl(q^{m}-1\bigr)[n]_q!.
\]
The coefficients combine by the single identity
$\bigl(q^{k+1}-1\bigr) + q^{k+1}\bigl(q^{\,n-k}-1\bigr) = q^{\,n+1}-1$,
so the total is $(q^{n+1}-1)[n]_q! = [n+1]_q!$.
\end{proof}

\begin{corollary}[Positivity]\label{cor:pos}
If $q \ge 2$ and $k \le n$ then $B_q(n,k)>0$; otherwise Theorem \ref{thm:factid} would force
$[n]_q!=0$, contradicting Lemma \ref{lem:factpos}.
\end{corollary}

\begin{corollary}[Symmetry]\label{cor:symm}
If $q \ge 2$ and $k \le n$ then $B_q(n,k) = B_q(n,n-k)$.
\end{corollary}

\begin{proof}
Apply Theorem \ref{thm:factid} at $k$ and at $n-k$; the common nonzero factor
$[k]_q!\,[n-k]_q!$ cancels in the integral domain $\Z$.
\end{proof}

\subsection{Exactness of the defining division}

\begin{lemma}\label{lem:num}
For $q \ge 1$ the natural-number product $\prod_{i<k}(q^{n}-q^{i})$ agrees with the same product
computed in $\Z$: for $k \le n$ each factor is non-negative, and for $k>n$ the index $i=n$
contributes a zero factor on both sides.
\end{lemma}

\begin{lemma}\label{lem:factorpow}
For $k \le n$, over $\Z$,
$\prod_{i<k}\bigl(q^{n}-q^{i}\bigr) = q^{\binom{k}{2}}\prod_{i<k}\bigl(q^{\,n-i}-1\bigr)$
with $\binom{k}{2}=\sum_{i<k}i$; pull $q^{i}$ out of the $i$-th factor.
\end{lemma}

\begin{lemma}\label{lem:desc}
For $k \le n$, over $\Z$,
$\bigl(\prod_{i<k}(q^{\,n-i}-1)\bigr)\cdot[n-k]_q! = [n]_q!$. Induct on $k$, peeling the factor
$q^{\,n-k}-1$ off the descending product and merging it with $[n-k-1]_q!$.
\end{lemma}

\begin{lemma}\label{lem:den}
Over $\Z$, $\prod_{i<k}(q^{k}-q^{i}) = q^{\binom{k}{2}}[k]_q!$, strictly positive for $q\ge 2$.
This is Lemmas \ref{lem:factorpow} and \ref{lem:desc} at $n=k$.
\end{lemma}

\begin{theorem}[Exactness]\label{thm:exact}
Let $q \ge 2$. For all $n,k$,
\[
 \Bigl(\prod_{i<k}(q^{k}-q^{i})\Bigr)\cdot B_q(n,k) \;=\; \prod_{i<k}(q^{n}-q^{i}),
\]
so the division defining $\binom{n}{k}_q$ is exact and $\binom{n}{k}_q = B_q(n,k)$.
\end{theorem}

\begin{proof}
For $k>n$ both sides vanish. For $k \le n$, use Lemma \ref{lem:den} on the left and Lemma
\ref{lem:factorpow} on the right; cancelling $q^{\binom{k}{2}}>0$ reduces the claim to
$[k]_q!\,B_q(n,k) = \prod_{i<k}(q^{\,n-i}-1)$, which follows from Theorem \ref{thm:factid} and
Lemma \ref{lem:desc} after multiplying by the positive integer $[n-k]_q!$. Lemma \ref{lem:num}
transfers the statement to $\mathbb{N}$, and division by the positive denominator gives the last
claim.
\end{proof}

From now on we write $\binom{n}{k}_q$ for both functions.

\subsection{Main theorems}

\begin{theorem}[$q$-Pascal recursion]\label{thm:pascal}
For every $q \ge 2$ and all $n,k \ge 0$,
\[
 \binom{n+1}{k+1}_{\!q} = \binom{n}{k}_{\!q} + q^{\,k+1}\binom{n}{k+1}_{\!q}.
\]
\end{theorem}

\begin{theorem}[Symmetry at an arbitrary base]\label{thm:symm}
For every $q \ge 2$ and $k \le n$, $\binom{n}{k}_q = \binom{n}{n-k}_q$.
\end{theorem}

\begin{theorem}[Positivity and boundary values]\label{thm:posbd}
For $q \ge 2$: $\binom{n}{k}_q>0$ for $k \le n$, $\binom{n}{k}_q = 0$ for $k>n$, and
$\binom{n}{0}_q=\binom{n}{n}_q=1$.
\end{theorem}

\begin{theorem}[First column]\label{thm:col1}
For $q \ge 2$, $\binom{n}{1}_q = \sum_{i=0}^{n-1}q^{i} = 1+q+\cdots+q^{\,n-1}$; equivalently
$\binom{n+1}{1}_q = 1 + q\binom{n}{1}_q$. Induct on $n$ using Theorem \ref{thm:pascal} at $k=0$.
\end{theorem}

\begin{theorem}[Dual $q$-Pascal recursion]\label{thm:dual}
For every $q\ge 2$ and all $n,k$,
\[
 \binom{n+1}{k+1}_{\!q} = q^{\,n-k}\binom{n}{k}_{\!q} + \binom{n}{k+1}_{\!q}.
\]
\end{theorem}

\begin{proof}
For $k>n$ all three terms vanish, and for $k=n$ both sides equal $1$. For $k<n$ write
$n-k=m+1$; by Theorem \ref{thm:symm},
$\binom{n+1}{k+1}_q = \binom{n+1}{n-k}_q = \binom{n+1}{m+1}_q$, which expands by Theorem
\ref{thm:pascal} as $\binom{n}{m}_q + q^{m+1}\binom{n}{m+1}_q$. Converting both terms back by
symmetry, using $n-m=k+1$ and $m+1=n-k$, gives the claim.
\end{proof}

\subsection{The Galois numbers}

\begin{lemma}\label{lem:Sreindex}
$S_q(n) = \sum_{k=0}^{n} q^{k+1}\binom{n}{k+1}_q + 1$: reindex, the $k=0$ term contributing
$\binom{n}{0}_q=1$ and the new top term vanishing.
\end{lemma}

\begin{theorem}\label{thm:Grec1}
For $q \ge 2$, $G_q(n+1) = G_q(n) + S_q(n)$.
\end{theorem}

\begin{proof}
$G_q(n+1) = 1 + \sum_{k=0}^{n}\binom{n+1}{k+1}_q$. Apply Theorem \ref{thm:pascal} termwise and
split: the first parts sum to $G_q(n)$, and the second parts together with the leading $1$ give
$S_q(n)$ by Lemma \ref{lem:Sreindex}.
\end{proof}

\begin{theorem}\label{thm:Grec2}
For $q \ge 2$, $S_q(n+1) = q^{\,n+1}G_q(n) + S_q(n)$.
\end{theorem}

\begin{proof}
Reindex $S_q(n+1) = 1 + \sum_{k=0}^{n}q^{k+1}\binom{n+1}{k+1}_q$ and apply Theorem \ref{thm:dual}:
for $k \le n$,
\[
 q^{k+1}\binom{n+1}{k+1}_{\!q}
 = q^{k+1}q^{\,n-k}\binom{n}{k}_{\!q} + q^{k+1}\binom{n}{k+1}_{\!q}
 = q^{\,n+1}\binom{n}{k}_{\!q} + q^{k+1}\binom{n}{k+1}_{\!q}.
\]
Summing, the first parts give $q^{n+1}G_q(n)$ and the rest is $S_q(n)$ by Lemma
\ref{lem:Sreindex}.
\end{proof}

\begin{theorem}[Three-term recursion for the Galois numbers]\label{thm:galois}
For $q \ge 2$ and all $n \ge 0$,
\[
 G_q(n+2) \;=\; 2\,G_q(n+1) \;+\; \bigl(q^{\,n+1}-1\bigr)G_q(n).
\]
\end{theorem}

\begin{proof}
By Theorem \ref{thm:Grec1}, $G_q(n+2)=G_q(n+1)+S_q(n+1)$ and $S_q(n)=G_q(n+1)-G_q(n)$.
Substituting Theorem \ref{thm:Grec2},
$G_q(n+2)=G_q(n+1)+q^{n+1}G_q(n)+G_q(n+1)-G_q(n)$.
\end{proof}

\begin{proposition}\label{prop:small}
For $q \ge 2$: $G_q(0)=1$, $G_q(1)=2$, $G_q(2)=1+(1+q)+1=q+3$.
\end{proposition}

\begin{corollary}\label{cor:tables}
$G_2(n)$ for $n=0,\dots,5$ is $1,2,5,16,67,374$; $G_3(n)$ for $n=0,\dots,4$ is $1,2,6,28,212$,
and $G_3(4)=2\cdot 28+(3^{3}-1)\cdot 6=212$ follows from Theorem \ref{thm:galois} alone. At the
non-prime base $q=4$: $\binom{2}{1}_4 = 5$, $\binom{3}{1}_4=\binom{3}{2}_4=21$ and
$\sum_{k\le 3}\binom{3}{k}_4 = 44$; at $q=6$, $\binom{5}{2}_6=\binom{5}{3}_6$. These bases are
inaccessible to a subspace argument over $\Z/q$, since neither $\Z/4$ nor $\Z/6$ is a field.
\end{corollary}

\section{Counting subgroups of a finite group}\label{sec:groups}

\subsection{Coprime products}

\begin{lemma}[Root extraction]\label{lem:root}
Let $A$ be finite, $K \le A$, $x \in A$, $n \ge 1$ with $\gcd(\ord(x),n)=1$. If $x^{n}\in K$ then
$x \in K$.
\end{lemma}

\begin{proof}
$\langle x^{n}\rangle \le \langle x\rangle$ and
$\ord(x^{n}) = \ord(x)/\gcd(\ord(x),n) = \ord(x)$, so the two cyclic groups coincide; hence
$x \in \langle x^{n}\rangle \le K$.
\end{proof}

\begin{lemma}[Coordinate splitting]\label{lem:split}
Let $G,H$ be finite with $\gcd(|G|,|H|)=1$ and $K \le G\times H$. If $(a,b)\in K$ then
$(a,1)\in K$ and $(1,b)\in K$.
\end{lemma}

\begin{proof}
With $m=|H|$ we have $(a,b)^{m}=(a^{m},1)\in K$ and $(a,1)^{m}=(a^{m},1)$. The order of $(a,1)$
divides $|G|$, coprime to $m$, so Lemma \ref{lem:root} gives $(a,1)\in K$; symmetrically for
$(1,b)$.
\end{proof}

\begin{theorem}[Product decomposition]\label{thm:proddec}
If $\gcd(|G|,|H|)=1$ then every $K \le G\times H$ equals $\pi_1(K)\times\pi_2(K)$, where
$\pi_1,\pi_2$ are the projections. No commutativity is assumed.
\end{theorem}

\begin{proof}
One inclusion is trivial. If $a \in \pi_1(K)$ and $b \in \pi_2(K)$, choose $(a,b_1),(a_2,b)\in K$;
by Lemma \ref{lem:split} both $(a,1)$ and $(1,b)$ lie in $K$, hence so does $(a,b)$.
\end{proof}

\begin{theorem}[Lattice splitting and multiplicativity]\label{thm:mult}
If $\gcd(|G|,|H|)=1$ then $\Sub(G\times H) \cong \Sub(G)\times\Sub(H)$ as ordered sets, via
$K \mapsto (\pi_1 K,\pi_2 K)$ with inverse $(A,B)\mapsto A\times B$; consequently
$\#\Sub(G\times H) = \#\Sub(G)\cdot\#\Sub(H)$.
\end{theorem}

\begin{proof}
The maps are mutually inverse by Theorem \ref{thm:proddec} together with
$\pi_1(A\times B)=A$, $\pi_2(A\times B)=B$. Monotonicity is clear, and if the projections of $K$
lie in those of $K'$ then rewriting both by Theorem \ref{thm:proddec} gives $K \le K'$.
\end{proof}

\begin{theorem}[Finite coprime families]\label{thm:pi}
If $G_1,\dots,G_n$ are finite with $\gcd(|G_i|,|G_j|)=1$ for $i \ne j$, then
$\#\Sub\bigl(\prod_i G_i\bigr) = \prod_i \#\Sub(G_i)$.
\end{theorem}

\begin{proof}
Induction on $n$, splitting off $G_1$: its order is coprime to $\prod_{i\ge 2}|G_i|$ because
coprimality is preserved by products. Apply Theorem \ref{thm:mult}; the base case is the trivial
group, with one subgroup.
\end{proof}

Since a finite abelian group is the product of its primary components, whose orders are pairwise
coprime, this reduces subgroup counting to $p$-groups.

\subsection{Cyclic groups}

\begin{lemma}\label{lem:cycex}
In a cyclic group of order $N$ with generator $g$, for $d \mid N$ the subgroup
$\langle g^{N/d}\rangle$ has order $d$.
\end{lemma}

\begin{lemma}\label{lem:cycuniq}
In a finite cyclic group $G$, a subgroup $L$ of order $d$ equals the kernel of $x \mapsto x^{d}$;
indeed $L$ is contained in that kernel, which has order $\gcd(d,|G|)=d$.
\end{lemma}

\begin{theorem}[Divisor count]\label{thm:divcount}
A finite cyclic group of order $N$ has exactly $d(N)$ subgroups, one of each order dividing $N$.
\end{theorem}

\begin{proof}
By Lemma \ref{lem:cycuniq} the map $L \mapsto |L|$ is injective on $\Sub(G)$; by Lagrange it lands
in the divisors of $N$, and by Lemma \ref{lem:cycex} it is onto them.
\end{proof}

\begin{corollary}\label{cor:cycpp}
A cyclic group of order $p^{r}$ has $r+1$ subgroups; in particular $\#\Sub(\Z/4)=3$.
\end{corollary}

\subsection{Groups of order $p^{2}$ and exponent $p$}

\begin{lemma}\label{lem:lines}
If $G$ has exponent $p$ and $x \ne 1$ then $|\langle x\rangle| = p$; conversely if $|L|=p$ and
$1 \ne x \in L$ then $L = \langle x\rangle$.
\end{lemma}

\begin{theorem}[The $p+1$ lines]\label{thm:p1lines}
If $|G|=p^{2}$ and $G$ has exponent $p$, then $G$ has exactly $p+1$ subgroups of order $p$.
\end{theorem}

\begin{proof}
The map $x \mapsto \langle x\rangle$ from non-identity elements to subgroups of order $p$ is well
defined by Lemma \ref{lem:lines}, and the fibre over $L$ is the set of non-identity elements of
$L$, of size $p-1$. Fibring gives $p^{2}-1 = \#\{L\}\cdot(p-1)$, so $\#\{L\} = p+1$.
\end{proof}

\begin{theorem}\label{thm:p3}
If $|G|=p^{2}$ and $G$ has exponent $p$ then $\#\Sub(G) = p+3$.
\end{theorem}

\begin{proof}
Subgroup orders are $1$, $p$ or $p^{2}$ by Lagrange; the extremes give one subgroup each and
Theorem \ref{thm:p1lines} gives $p+1$ in the middle.
\end{proof}

\begin{corollary}\label{cor:contrast}
A cyclic group of order $p^{2}$ has $3$ subgroups and a group of order $p^{2}$ and exponent $p$
has $p+3$; these differ for every prime $p$. In particular
$\#\Sub(\Z/4)=3 \ne 5 = \#\Sub\bigl((\Z/2)^{2}\bigr)$.
\end{corollary}

\begin{corollary}\label{cor:twelve}
$\#\Sub(\Z/12) = 3\cdot 2 = 6 = d(12)$, while $\#\Sub\bigl((\Z/2)^{2}\times\Z/3\bigr) = 5\cdot 2 = 10$.
\end{corollary}

\subsection{Elementary abelian groups and the Galois numbers}

The group $(\Z/p)^{r}$ is an $r$-dimensional $\F_p$-vector space and its subgroups are its
subspaces. Counting ordered linearly independent $k$-tuples in $\prod_{i<k}(p^{r}-p^{i})$ ways and
fibring over their spans --- the tuples spanning a fixed $k$-dimensional $W$ being exactly the
bases of $W$, of which there are $\prod_{i<k}(p^{k}-p^{i})$ --- gives
$\#\{W : \dim W = k\} = \binom{r}{k}_p$ for $k \le r$.

\begin{theorem}\label{thm:eacount}
$\#\Sub\bigl((\Z/p)^{r}\bigr) = G_p(r) = \sum_{k=0}^{r}\binom{r}{k}_p$.
\end{theorem}

Consistency: $G_p(2) = p+3$ by Proposition \ref{prop:small}, matching Theorem \ref{thm:p3}, and
the $p+1$ lines are the $\binom{2}{1}_p = 1+p$ one-dimensional subspaces.

\begin{theorem}[Mixed elementary abelian]\label{thm:mixed}
For distinct primes $p \ne q$ and $r,s \ge 0$,
$\#\Sub\bigl((\Z/p)^{r}\times(\Z/q)^{s}\bigr) = G_p(r)\,G_q(s)$.
\end{theorem}

\begin{proof}
The orders $p^{r}$ and $q^{s}$ are coprime; apply Theorems \ref{thm:mult} and \ref{thm:eacount}.
\end{proof}

\section{Intermediate fields of a Hilbert class field}\label{sec:fields}

Let $(H/K,e)$ be a class field datum.

\begin{theorem}[Counting principle]\label{thm:principle}
The number of intermediate fields $K \subseteq F \subseteq H$ equals $\#\Sub(\Cl(K))$, and the
field $F_A$ attached to $A \le \Cl(K)$ satisfies $[F_A:K] = [\Cl(K):A]$ and $[H:F_A]=|A|$.
\end{theorem}

\begin{theorem}[Cyclic class group]\label{thm:cyc}
If $\Cl(K)$ is cyclic of order $n$, the datum has exactly $d(n)$ intermediate fields, one of each
degree $m \mid n$ over $K$.
\end{theorem}

\begin{theorem}[Elementary abelian class group]\label{thm:ea}
If $\Cl(K) \cong (\Z/p)^{r}$, the datum has exactly $G_p(r) = \sum_{k \le r}\binom{r}{k}_p$
intermediate fields, and for each $0 \le k \le r$ exactly $\binom{r}{k}_p$ of them have degree
$p^{k}$ over $K$. The degrees that occur are exactly $p^{k}$, $0 \le k \le r$.
\end{theorem}

\begin{proof}
A subspace $W$ of dimension $j$ has index $p^{\,r-j}$, so it produces a field of degree
$p^{\,r-j}$ over $K$. With $k=r-j$, the count is the number of subspaces of dimension $r-k$,
namely $\binom{r}{r-k}_p = \binom{r}{k}_p$ by Theorem \ref{thm:symm}. Positivity (Theorem
\ref{thm:posbd}) shows every degree $p^{k}$, $k \le r$, occurs.
\end{proof}

Symmetry of the Gaussian binomial is exactly what converts an index count into a degree count with
the same index, whence the palindromic degree distributions below.

\begin{corollary}[Klein four class group, $p=r=2$]\label{cor:klein}
If $\Cl(K)\cong(\Z/2)^{2}$ the datum has $G_2(2)=5$ intermediate fields, of which
$\binom{2}{1}_2 = 3$ are quadratic; the degree multiset is $\{1,2,2,2,4\}$.
\end{corollary}

\begin{corollary}[Rank three at $p=2$]\label{cor:rank3}
If $\Cl(K)\cong(\Z/2)^{3}$ the datum has $G_2(3)=16$ intermediate fields with degree distribution
$1,7,7,1$ in degrees $1,2,4,8$, the sevens being $\binom{3}{1}_2 = \binom{3}{2}_2 = 1+2+4$.
\end{corollary}

\begin{theorem}[Mixed class group]\label{thm:mixedfields}
If $\Cl(K)\cong(\Z/p)^{r}\times(\Z/q)^{s}$ with $p \ne q$ prime, the datum has exactly
$G_p(r)G_q(s)$ intermediate fields; e.g.\ $5\cdot 2 = 10$ for $(\Z/2)^{2}\times\Z/3$ at class
number twelve, against $d(12)=6$ for the cyclic class group of the same order.
\end{theorem}

\begin{theorem}[The count is not a function of the class number]\label{thm:notclassnumber}
There are finite abelian groups of equal order with different subgroup counts: $3 \ne 5$ at order
$4$, $6 \ne 10$ at order $12$, $3 \ne p+3$ at order $p^{2}$. Hence no function of $h_K$ alone
predicts the number of intermediate fields of a Hilbert class field.
\end{theorem}

\section{Algorithms}\label{sec:algos}

\subsection{Row-by-row $q$-Pascal triangle}
To tabulate $\binom{n}{k}_q$ for $k \le n \le N$, start from the row $[1]$ and iterate
$\mathrm{row}_{n+1}[0]=1$, $\mathrm{row}_{n+1}[k+1] = \mathrm{row}_n[k] + q^{k+1}\mathrm{row}_n[k+1]$.
This costs $\Theta(N^{2})$ big-integer operations and, unlike the defining quotient, never forms a
large product only to divide it away. Correctness is Theorem \ref{thm:exact}.

\subsection{Galois numbers by the three-term recursion}
$G_q(0)=1$, $G_q(1)=2$, then $G_q(n+2)=2G_q(n+1)+(q^{n+1}-1)G_q(n)$ (Theorem \ref{thm:galois}):
$\Theta(N)$ arithmetic operations for $G_q(N)$, against $\Theta(N^{2})$ for summing a triangle row,
a real saving since $G_q(N)$ has $\Theta(N^{2}\log q)$ bits.

\subsection{Subgroup count of a finite abelian group}
Given the primary decomposition $\bigoplus_p\bigoplus_i \Z/p^{\lambda_{p,i}}$: multiply the
per-prime counts (Theorem \ref{thm:pi}); for a cyclic component of order $N$ return $d(N)$
(Theorem \ref{thm:divcount}), for $p^{r}$ cyclic return $r+1$, and for $(\Z/p)^{r}$ return
$G_p(r)$ (Theorem \ref{thm:eacount}). This settles every abelian group whose primary components
are cyclic or elementary abelian, hence all the class field applications above; the general
$p$-component requires the Birkhoff--Hall count.

\section{Applications and cross-checks}\label{sec:apps}

\emph{Falsifiable predictions.} A Klein four class group yields exactly five intermediate fields
with degrees $\{1,2,2,2,4\}$; a class group $(\Z/2)^{3}$ yields exactly sixteen with distribution
$1,7,7,1$; a class group $(\Z/2)^{2}\times\Z/3$ yields exactly ten. Each is a single integer that
an explicit computation confirms or refutes.

\emph{Two independent proofs at order $p^{2}$.} The count $p+3$ arises both by partitioning the
$p^{2}-1$ non-identity elements into lines (Theorem \ref{thm:p3}) and as the Galois number
$G_p(2)$ (Proposition \ref{prop:small}).

\emph{Beyond finite geometry.} Since Theorems \ref{thm:exact}--\ref{thm:dual} hold for all
$q \ge 2$, they apply where no field of $q$ elements exists; e.g.\ $\binom{5}{2}_6 = \binom{5}{3}_6$
and $\binom{2}{1}_4 = 1 + 4\cdot 1 = 5$. This is what the standard combinatorial readings of
$\binom{n}{k}_q$ --- generating function for partitions in a $k\times(n-k)$ box, $q$-analogues in
$q$-series and quantum groups --- require.

\emph{Integrality.} Theorem \ref{thm:exact} states the divisibility
$\prod_{i<k}(q^{k}-q^{i}) \mid \prod_{i<k}(q^{n}-q^{i})$ in $\Z$ for all $q \ge 2$, $k \le n$,
proved by exhibiting the quotient as the solution of a recursion.

\section{Discussion and future work}\label{sec:future}

The methodological point of Section \ref{sec:qbin} is that a quotient definition can be replaced
by a recursive one, with equality proved rather than assumed, buying uniformity in the base. The
point of Section \ref{sec:groups} is that subgroup counting is lattice-theoretic: coprime
splitting is an isomorphism of ordered sets, available without commutativity.

\begin{enumerate}
\item \emph{General finite abelian class groups.} Combining Theorem \ref{thm:pi} with the
Birkhoff--Hall count of subgroups of type $\mu$ in an abelian $p$-group of type $\lambda$ would
give $\#\Sub(A)$ for every finite abelian $A$. The first genuinely new case is $\lambda=(2,1)$.
\item \emph{Structure of the rows.} Unimodality and $q$-log-concavity of
$\bigl(\binom{n}{k}_q\bigr)_k$, and the asymptotics $G_q(n) \sim c\,q^{n^{2}/4}$, are natural next
targets for the recursion-based approach; at $q=1$ the theory degenerates correctly to Pascal's
rule and $G_1(n)=2^{n}$.
\item \emph{Unconditional instances.} For $K=\Q(\sqrt{-5})$, of class number $2$ with Hilbert
class field $K(i)$, the count becomes the unconditional statement that there are exactly
$G_2(1)=2$ intermediate fields; for $K = \Q(\sqrt{-21})$, class group $(\Z/2)^{2}$, the prediction
is five.
\item \emph{Splitting laws.} Demanding that the identification $\Gal(H/K)\cong\Cl(K)$ be the Artin
map refines each count into a splitting law: in the elementary abelian case, the primes splitting
completely in the degree-$p^{k}$ field attached to a subspace $W$ are exactly those whose class
lies in $W$.
\item \emph{Genus theory.} For imaginary quadratic $K$ with $t$ prime discriminant divisors,
$\Cl/\Cl^{2}$ has order $2^{t-1}$ and cuts out the genus field; when $\Cl(K)$ is elementary
abelian of rank $r$ the genus field is the whole Hilbert class field and $r=t-1$.
\end{enumerate}

\section*{Summary of results}

For every base $q \ge 2$: the quotient defining $\binom{n}{k}_q$ is an exact division; the
$q$-factorial identity $[k]_q![n-k]_q!\binom{n}{k}_q = [n]_q!$ holds for $k \le n$; $q$-Pascal and
its dual hold; $\binom{n}{k}_q = \binom{n}{n-k}_q > 0$ for $k \le n$; and
$\binom{n}{1}_q = 1+q+\cdots+q^{n-1}$. The Galois numbers satisfy
$G_q(n+2)=2G_q(n+1)+(q^{n+1}-1)G_q(n)$ with $G_q(2)=q+3$, giving $1,2,5,16,67,374$ at $q=2$,
$G_3(4)=212$ and $G_4(3)=44$. Subgroup counts multiply over coprime direct factors; a cyclic group
of order $N$ has $d(N)$ subgroups; a group of order $p^{2}$ and exponent $p$ has $p+3$. Hence a
class field datum has $d(n)$, $G_p(r)$ or $G_p(r)G_q(s)$ intermediate fields in the cyclic,
elementary abelian and mixed cases respectively, with $\binom{r}{k}_p$ of degree $p^{k}$ in the
elementary abelian case --- and the total depends on the class group, not on the class number.

