from typing import List

def q_pascal_triangle(q: int, N: int) -> List[List[int]]:
    """Rows 0..N of the Gaussian binomial triangle in base q.

    Uses the q-Pascal recursion
        binom(n+1, k+1)_q = binom(n, k)_q + q^{k+1} * binom(n, k+1)_q,
    which is valid for every integer base q >= 2 and never forms the large
    products of the defining quotient.
    """
    rows: List[List[int]] = [[1]]
    for _ in range(N):
        prev = rows[-1]
        row = [1]
        for k in range(len(prev)):
            above_right = prev[k + 1] if k + 1 < len(prev) else 0
            row.append(prev[k] + q ** (k + 1) * above_right)
        rows.append(row)
    return rows


def gaussian_binomial(q: int, n: int, k: int) -> int:
    """binom(n,k)_q, zero when k > n."""
    if k > n:
        return 0
    return q_pascal_triangle(q, n)[n][k]


def gaussian_binomial_by_quotient(q: int, n: int, k: int) -> int:
    """The defining quotient, computed as an exact integer division.

    Raises if the division is not exact -- which, for q >= 2, never happens:
    that is the exactness theorem.
    """
    num, den = 1, 1
    for i in range(k):
        num *= q ** n - q ** i
        den *= q ** k - q ** i
    if num == 0:
        return 0
    if num % den:
        raise ArithmeticError("non-exact division")
    return num // den


if __name__ == "__main__":
    for q in (2, 3, 4, 6):
        assert all(gaussian_binomial(q, n, k) == gaussian_binomial_by_quotient(q, n, k)
                   for n in range(8) for k in range(9))
        assert all(gaussian_binomial(q, n, k) == gaussian_binomial(q, n, n - k)
                   for n in range(8) for k in range(n + 1))
    print(q_pascal_triangle(2, 5)[-1])   # [1, 31, 155, 155, 31, 1]

from typing import Dict, List, Sequence

def factorize(n: int) -> Dict[int, int]:
    """Prime factorisation {p: exponent}."""
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


def divisor_count(n: int) -> int:
    """d(n) = number of positive divisors, from the factorisation."""
    total = 1
    for e in factorize(n).values():
        total *= e + 1
    return total


def galois_number(q: int, n: int) -> int:
    """G_q(n) by the three-term recursion."""
    if n == 0:
        return 1
    if n == 1:
        return 2
    prev, cur = 1, 2
    for m in range(n - 1):
        prev, cur = cur, 2 * cur + (q ** (m + 1) - 1) * prev
    return cur


def subgroup_count(invariants: Sequence[int]) -> int:
    """Number of subgroups of Z/n_1 x ... x Z/n_t, hence the number of
    intermediate fields of a Hilbert class field with that class group.

    Multiplicativity over the (pairwise coprime) primary components reduces the
    problem to one prime at a time; each p-component must be cyclic -- count
    r+1 -- or elementary abelian -- count G_p(r).
    """
    parts: Dict[int, List[int]] = {}
    for n in invariants:
        for p, e in factorize(n).items():
            parts.setdefault(p, []).append(e)
    total = 1
    for p, exps in parts.items():
        if len(exps) == 1:
            total *= exps[0] + 1
        elif all(e == 1 for e in exps):
            total *= galois_number(p, len(exps))
        else:
            raise NotImplementedError(
                "p-component of type %s needs the Birkhoff-Hall count"
                % sorted(exps, reverse=True))
    return total


def intermediate_field_degrees(p: int, r: int) -> List[tuple]:
    """(degree over K, number of intermediate fields) for class group (Z/p)^r."""
    rows = [[1]]
    for _ in range(r):
        prev = rows[-1]
        row = [1]
        for k in range(len(prev)):
            nxt = prev[k + 1] if k + 1 < len(prev) else 0
            row.append(prev[k] + p ** (k + 1) * nxt)
        rows.append(row)
    return [(p ** k, rows[r][k]) for k in range(r + 1)]


if __name__ == "__main__":
    assert subgroup_count([4]) == 3            # cyclic of order 4
    assert subgroup_count([2, 2]) == 5         # Klein four
    assert subgroup_count([12]) == 6 == divisor_count(12)
    assert subgroup_count([2, 2, 3]) == 10     # (Z/2)^2 x Z/3
    assert subgroup_count([2, 2, 2]) == 16
    print(intermediate_field_degrees(2, 3))    # [(1,1),(2,7),(4,7),(8,1)]
